// _COORD_IO_COVERAGE_v1_: the coverage matrix of coord I/O for every kept market (test/io/coverage.json, generated by
// scripts/io-coverage.mjs from coord's catalogue and test/io/op-map.json):
//   1. the markets are the SDK's own (MOONBEAM_LISTS_ON), the stages the five lights, the directions read and write;
//   2. every market x stage x dir cell has rows, and every row has a fixture on disk or a named gap with a reason and why;
//   3. coverage.json is current with the map and the fixtures, and carried no issue when it was generated (io:check);
//   4. the ratchet: the gap count may only go down (test/io/gaps.baseline.json);
//   5. docs/io-coverage.md is exactly what the coverage renders;
//   6. no live fixture carries a payee, signer or treasury-like field.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { MOONBEAM_LISTS_ON } from '../../src/market/index.js';
import { LIGHT_IDS } from '../../src/playground/index.js';
// @ts-expect-error: a plain ES module shared with the generator
import { GAP_REASONS, SOURCES, buildCoverage, expandRows, fixturesOnDisk, gapCount, renderDoc, shapeIssues, summaryOf } from '../../scripts/io-coverage-lib.mjs';

const root = join(__dirname, '..', '..');
const read = (p: string) => JSON.parse(readFileSync(join(root, p), 'utf8'));
const cov = read('test/io/coverage.json');
const map = read('test/io/op-map.json');
const baseline = read('test/io/gaps.baseline.json');
const fixtures: Map<string, { source: string; coord_sha: string; response: { body: unknown } }> = fixturesOnDisk(root);
type Cell = { market: string; stage: string; dir: string; op: string | null; chain: number | null; cite: string | null; fixture?: string | null; source?: string; gap?: { reason: string; why: string } };
const cells: Cell[] = cov.cells;

describe('_COORD_IO_COVERAGE_v1_ coverage: every kept market, every stage, both directions', () => {
  it('the markets are the ones Moonbeam lists on, the stages the five lights', () => {
    expect([...cov.markets].sort()).toEqual([...MOONBEAM_LISTS_ON].sort());
    expect(cov.stages).toEqual([...LIGHT_IDS]);
    expect(cov.dirs).toEqual(['read', 'write']);
    expect(cov.coord.sha).toMatch(/^[0-9a-f]{40}$/);
  });
  it('every market x stage x dir cell has a fixture or a named gap', () => {
    const missing: string[] = [];
    for (const m of cov.markets) for (const st of cov.stages) for (const d of cov.dirs) {
      const mine = cells.filter((c) => c.market === m && c.stage === st && c.dir === d);
      if (!mine.length) missing.push(`${m}/${st}/${d}`);
    }
    expect(missing).toEqual([]);
    for (const c of cells) {
      const where = `${c.market}/${c.stage}/${c.dir} ${c.op ?? '(no op)'}`;
      expect(!!c.fixture !== !!c.gap, `${where}: a fixture or a gap, not both`).toBe(true);
      if (c.gap) { expect(GAP_REASONS, where).toContain(c.gap.reason); expect(c.gap.why.length, `${where}: the gap says why`).toBeGreaterThan(10); }
      else { expect(SOURCES, where).toContain(c.source); expect(fixtures.get(c.fixture!)?.source, `${where}: ${c.fixture} on disk`).toBe(c.source); }
      if (c.op) expect(c.cite, `${where} cites coord's file:line`).toMatch(/^lang\/cue\/api-operations\.cue:\d+$/);
    }
  });
  it('coverage.json is current with the op-map and the fixtures, and io:check found no issue', () => {
    const rows = expandRows(map);
    expect(cells.map((c) => `${c.market}/${c.stage}/${c.dir}/${c.op}`)).toEqual(rows.map((r: Cell) => `${r.market}/${r.stage}/${r.dir}/${r.op}`));
    expect(rows.filter((r: Cell) => r.fixture).map((r: Cell) => r.fixture).sort()).toEqual([...fixtures.keys()].sort());
    expect(cov.issues).toEqual([]);
    expect(cov.summary).toEqual(summaryOf(map, cells));
    for (const [p, f] of fixtures) expect(f.coord_sha, p).toMatch(/^[0-9a-f]{40}$/);
  });
  it('the ratchet: the gap count only goes down', () => {
    const g = gapCount(cov);
    expect(g.total, 'more gaps than test/io/gaps.baseline.json allows').toBeLessThanOrEqual(baseline.total);
    for (const r of GAP_REASONS) expect(g.by[r], `${r} gaps`).toBeLessThanOrEqual(baseline.by[r] ?? 0);
  });
  it('docs/io-coverage.md is the rendered coverage', () => {
    expect(readFileSync(join(root, 'docs/io-coverage.md'), 'utf8')).toBe(renderDoc(cov));
  });
  it('no live fixture carries a payee, signer or treasury-like field', () => {
    const bad: string[] = [];
    const DROP = /^(fee_to|fee_payee|pay_?to|payTo|payee|payees|treasury|safe|deployer|signer|signers|workers|worker|requester)$/i;
    const walk = (v: unknown, p: string, f: string) => {
      if (Array.isArray(v)) v.forEach((x) => walk(x, `${p}[]`, f));
      else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) { if (DROP.test(k)) bad.push(`${f}: ${p}.${k}`); walk(x, `${p}.${k}`, f); }
    };
    for (const [p, f] of fixtures) if (f.source === 'live') walk(f.response.body, '', p);
    expect(bad).toEqual([]);
  });
});

describe('_COORD_IO_COVERAGE_v1_ io:check catches a coord release that moved', () => {
  const coordOf = (ops: Record<string, unknown>[], bodies: Record<string, unknown> = {}) => ({
    sha: 'f'.repeat(40), ops: new Map(ops.map((o) => [`${o['method']} ${o['name']}`, o])), bodies, cue: [], bodiesCue: [], listingCue: [], sign: {} });
  it('a new op tagged to a kept market with no cell is an issue', () => {
    const c = coordOf([{ method: 'GET', name: 'x402/new-door', target: '/api/x', summary: '', returns: '{ a }' }]);
    const issues: string[] = buildCoverage(c, map, new Map()).issues;
    expect(issues.some((i) => i.startsWith('new op: GET x402/new-door (tagged x402-base)'))).toBe(true);
    expect(issues.some((i) => i.startsWith('gone: GET listed'))).toBe(true);
  });
  it('a request or answer field coord no longer declares is an issue', () => {
    const c = coordOf([{ method: 'POST', name: 'pipe/ack', request: 'PipeAck', summary: '', returns: '{ id, state: acked }' }],
      { PipeAck: { type: 'object', required: ['id'], properties: { id: { type: 'string' }, by: { type: 'string' } } } });
    const fx = { op: 'POST pipe/ack', source: 'contract', request: { method: 'POST', path: '/v1/pipe/ack', query: {}, body: { id: '0x1', by: 'me', extra: 1 } }, response: { status: 200, body: { id: '0x1', state: 'acked', more: true } } };
    expect(shapeIssues(c, fx)).toEqual(['body:extra', 'response:more']);
    expect(shapeIssues(c, { ...fx, request: { ...fx.request, body: { by: 'me' } }, response: { status: 200, body: { id: '0x1' } } })).toEqual(['required:id']);
  });
});
